      summaryZh: "Fabian 介绍自己的家庭、父母和姐姐的日常生活。",
      contentDe: `Ich heiße Fabian und bin 14 Jahre alt. Ich gehe jetzt in die neunte Klasse im Gymnasium Kalletal-Hohenhausen. Ich spiele Fußball bei BHK Kalletal und bin dort in der F-Jugend-Mannschaft.

Meine Familie lebt in Kalletal-Hohenhausen in Nordrhein-Westfalen. Wir haben ein Haus dort. Es liegt in einer ruhigen Straße und hat einen sehr schönen Garten.

Caroline ist meine Schwester. Sie ist 15 Jahre alt und geht jetzt auf das Marianne-Weber-Gymnasium in Lemgo. Sie ist in der zehnten Klasse. Sie hat ein Kaninchen. Es heißt „Kira“. Meine Schwester fährt sehr gern Rad. Sie schwimmt auch gut.

Karin Nolting ist meine Mutter. Sie ist 39 Jahre alt und arbeitet als Kauffrau bei der Firma Huxoll in Kalletal-Hohenhausen. Sie arbeitet vormittags. Sie treibt in ihrer Freizeit viel Sport, zum Beispiel Rad fahren.

Mein Vater heißt Jürgen Nolting, 43 Jahre alt. Er arbeitet bei der Commerzbank AG Filiale Bielefeld in der Abteilung für Firmenkunden. In der Freizeit fährt er oft Rad. Er schwimmt auch sehr gern.`
