      tags: ["OCR", "阅读训练", "健康"],
      summaryZh: "运动鞋不只用于运动，也成了日常时尚；文章讨论它是否真的伤害双脚。",
      contentDe: `Junge Leute tragen sie nicht nur beim Sport, sondern auch in der Schule und in der Freizeit: Sportschuhe. Es gibt sie in allen Farben und Formen. Wer auch noch die richtige Marke trägt, der ist „in“.

Doch was ist mit der Gesundheit? Schaden Sportschuhe den Füßen? Sowohl Orthopäden als auch Mikrobiologen meinen, dass Sportschuhe nicht ungesund sind. Sie müssen aber genau passen und dem Fuß Halt geben.

Außerdem dürfen die Schuhe nicht aus Plastik sein. Die führen vielleicht nicht zu Problemen mit dem Fußskelett, dafür aber mit der Fußhygiene. Im Plastikschuh gibt es nämlich schnell ein ungesundes warmes Klima. Ebenso schnell gibt es Pilzkrankheiten. Wenn Jugendliche dann abends ihre Sportschuhe ausziehen, riechen die Schuhe oft furchtbar.`
