      tags: ["OCR", "阅读", "音乐"],
      summaryZh: "德国嘻哈组合“神奇四侠”如何把美国嘻哈转译为德国语境，并记录时代变化。",
      contentDe: `Wer sich mit aktueller Popmusik in Deutschland beschäftigt, kommt an den Fantastischen Vier nicht vorbei — textlich, musikalisch, soziologisch. Bereits Ende der Achtziger begannen Andy, Michi Beck, Smudo und Thomas D., das Phänomen Hiphop für die deutschen Verhältnisse zu übersetzen.

Die Geschichte der Band erzählt somit viel über die popkulturellen Ströme der alten Bundesrepublik. Am Anfang standen die Vorbilder aus England oder Amerika: Sie wurden kopiert und auf die konkrete Lebenssituation in Deutschland angepasst. Dabei entwickelten die vier Musiker einen eigenen Stil, der von Ironie, Wortspielen und einem genauen Blick auf den Alltag lebt.

Ihre Texte sind nicht nur Unterhaltung, sondern auch ein Dokument des Wandels: Sie zeigen, wie sich Sprache, Medien und Jugendkultur in Deutschland verändert haben. Wer die Band hört, hört deshalb immer auch ein Stück Zeitgeschichte.`
