      tags: ["OCR", "阅读", "跨文化"],
      summaryZh: "一位中国女性在德国学习、生活并写博士论文的经历：从“Blödchen”到“Brötchen”的转折点。",
      contentDe: `Ein Freund meines Vaters, ebenfalls ein Philosophieprofessor, meinte, die deutsche Sprache sei die Sprache der Philosophie, die für Frauen nicht geeignet sei, besonders für eine wie mich, die gern Gedichte schreibt. Nun lebe ich seit sechs Jahren in Deutschland, genauer gesagt, in Kiel.

Nebenbei erfahre ich, dass auch Chinesisch bei Deutschen einen merkwürdigen Ruf hat: das sogenannte Fachchinesisch. Die deutschen Studenten, die Chinesisch lernen, gelten unter ihrem Volk entweder als tapfer oder als komisch. Als ich einmal bei der Post einen Brief nach Peking schicken wollte, sagte der Angestellte hinter dem Schalter freundlich zu mir: „Eure Schriftzeichen sind wie Häuschen!“ Dieses Bild gefällt mir immer noch.

Deutsch zu lernen, war eine bittere Erfahrung für mich. Obwohl ich hart gekämpft habe, um alle grammatischen Regeln zu erlernen, erlaubte mir meine chinesische Zunge lange Zeit nicht, Deutsch auszusprechen. Eines Tages merkte ich plötzlich, dass ich nicht mehr „Blödchen“, sondern „Brötchen“ sagen konnte. Dieser Tag wurde zu einem Wendepunkt in meinem Leben in Deutschland.

Kurz danach bestand ich die Sprachprüfung und durfte neben meiner halben Stelle als Lektorin studieren. Trotzdem hatte ich, als ich im ersten Semester in einer Vorlesung unter Hunderten deutscher Studenten saß, ein Gefühl, als ob ich auf einer Wolke säße. Ich verstand so wenig, dass ich mich nur auf das laute Naseputzen der Studenten und das hinter Bart und Brille versteckte Gesicht des Professors konzentrierte. So schwer war Deutsch für mich.`
