      summaryZh: "巴登-符腾堡州如何通过学校、教会、工会与基金会合作，建立和平教育服务中心。",
      contentDe: `Am 30. Oktober 2014 unterzeichnete Kultusminister Andreas Stoch mit damals 14 Vertreterinnen und Vertretern aus dem Bereich der Friedensbewegung eine gemeinsame Erklärung zur Stärkung der Friedensbildung in den baden-württembergischen Schulen. Im Folgenden kamen noch drei weitere Partner hinzu, so dass das Vorhaben nun von insgesamt 17 zivilgesellschaftlichen Organisationen breite Unterstützung findet.

Zu den Unterzeichnern gehören neben kirchlichen Einrichtungen auch Gewerkschaften, Vereine und Verbände, die sich bereits seit vielen Jahren im Bereich der Friedensbildung engagieren. Auf Basis dieser gemeinsamen Erklärung kam schließlich ein Vertrag zwischen dem Kultusministerium, der Landeszentrale für politische Bildung sowie der Berghof Foundation zustande.

Kern dieses Vertrages ist die Einrichtung einer Servicestelle Friedensbildung, die in gemeinsamer Trägerschaft der Unterzeichner personell und organisatorisch bei der Landeszentrale angesiedelt ist. Seit dem 1. August 2015 agiert die Servicestelle als zentrale Beratungs-, Vernetzungs- und Kontaktstelle für alle Schulen des Landes sowie für staatliche, halb- und nichtstaatliche Akteure der Friedensbildung.`
